// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { openNewOwnerForm, fillOwnerFormWithoutEmail } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(150000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const playwrightRequest0: Record<string, any> = {
        "address": "12 Gate Road",
        "city": "Madison",
        "email": "gate.check@example.com",
        "firstName": "Gate",
        "lastName": "Check",
        "telephone": "6085550444"
    };

    await page.goto(baseUrl);
    await openNewOwnerForm(page);

    // On a pristine form the submit button is gated off.
    await expect(page.locator("#email")).toHaveValue("");
    await expect(page.getByRole("button", { name: "Add Owner" })).toBeDisabled();

    // A valid Email on its own does NOT satisfy the form: Email is optional, so it is
    // not one of the controls that gates submission.
    await page.locator("#email").fill(getValue(playwrightRequest0, "email"));
    await page.waitForTimeout(1500);
    await expect(page.locator("#email")).toHaveValue("gate.check@example.com");
    await expect(page.getByRole("button", { name: "Add Owner" })).toBeDisabled();

    // Filling only the required controls -- First Name, Last Name, Address, City, Telephone --
    // is what enables submission.
    await fillOwnerFormWithoutEmail(
        page,
        getValue(playwrightRequest0, "firstName"),
        getValue(playwrightRequest0, "lastName"),
        getValue(playwrightRequest0, "address"),
        getValue(playwrightRequest0, "city"),
        getValue(playwrightRequest0, "telephone"),
    );

    await expect(page.getByRole("button", { name: "Add Owner" })).toBeEnabled();
    // The email the user typed first is preserved through the rest of the form fill.
    await expect(page.locator("#email")).toHaveValue("gate.check@example.com");
});
